-- Molten Core (the pieces that are not tier 1): the Classic armor, jewelry, cloaks, shields and off-hands that drop there had no item row
-- (the WoW Forever client blanks them), so every one was an invalid loot item and nothing dropped. Rows from the
-- Classic item data: stats as budget shares, armor from the item level formula, Classic sell prices, Classic
-- equip and use spells as item effects, hotfix_data so the client shows them.
DELETE FROM `item_sparse` WHERE `ID` IN (14867,17065,17066,17109,17110,18823,18824,18829,18861,18870,18872,18875,19136,19142,19143,19144,19145,19146);
DELETE FROM `item_effect` WHERE `ID` BETWEEN 9900738 AND 9900761;
DELETE FROM `item_x_item_effect` WHERE `ID` BETWEEN 9900738 AND 9900761;
DELETE FROM `hotfix_data` WHERE `Id` BETWEEN 26113377 AND 26113442;
